using System;

public class VirtualMemoryCalculator
{
    public static long CalculateRequiredPages(long bytesNeeded)
    {
        if (bytesNeeded <= 0) return 0;
        const long PageSize = 4096;
        return (bytesNeeded + PageSize - 1) / PageSize;
    }

    public static void Main()
    {
        Console.WriteLine($"4096 bytes: {CalculateRequiredPages(4096)}");
        Console.WriteLine($"4097 bytes: {CalculateRequiredPages(4097)}");
    }
}
